//! Browser fallback generated from the same catalog served by the backend.

/// Render the complete mixer catalog as a typed browser module.
pub fn render_typescript() -> String {
    let json = serde_json::to_string_pretty(&crate::catalog())
        .expect("static device catalog is serializable");
    format!(
        "// @generated by `cargo run -p oc-device-schema --bin gen-device-catalog`.\n// Source of truth: crates/oc-device-schema. Do not edit by hand.\n\nimport type {{ DevicesCatalog }} from \"../types/devices\";\n\nexport const DEVICE_CATALOG: DevicesCatalog = {json};\n"
    )
}

#[cfg(test)]
mod tests {
    #[test]
    fn generated_device_typescript_is_current() {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../oc-gui/frontend/src/data/deviceCatalog.gen.ts");
        let on_disk = std::fs::read_to_string(path).expect("generated device catalog exists");
        assert_eq!(
            on_disk,
            super::render_typescript(),
            "run cargo run -p oc-device-schema --bin gen-device-catalog"
        );
    }
}
